# Parse cpc into list of codes per cohort row
def parse_cpc(s):
    if not s: return []
    try:
        arr = json.loads(s)
        codes = []
        for it in arr:
            if isinstance(it, dict):
                c = it.get('code')
                if c: codes.append(c)
        return codes
    except Exception:
        return []

cohort['cpc_codes'] = cohort['cpc'].map(parse_cpc)
print('rows with no cpc codes:', (cohort['cpc_codes'].str.len()==0).sum())
all_codes = set()
for lst in cohort['cpc_codes']:
    all_codes.update(lst)
print('Unique CPC codes in cohort:', len(all_codes))
print(list(all_codes)[:20])

